// The default core-asset skeleton for a project's OKF (#88). A fresh bundle
// starts here: a small set of standing, cross-linked assets the mediator
// maintains in-turn. Bodies are structural scaffolds and real repo conventions
// only — never fabricated decisions or history. index.md and log.md are
// generated by MemoryStore, so they are not seeded.
import type { MemoryDocInput } from "./memory.js";
import { MemoryStore } from "./memory.js";
import type { Db } from "../db.js";

/** Reciprocal-link footers back to the bundle-root routing table. */
const ROOT_BACK = "\n\nSee also [Core assets](core-assets.md).\n";
const NESTED_BACK = "\n\nSee also [Core assets](../core-assets.md).\n";

/**
 * The seeded skeleton. Each asset links back to core-assets.md, and
 * core-assets.md links out to each asset, so the Knowledge graph has edges from
 * the first render — not a disconnected pile. Titles/descriptions are distinct
 * so the near-dup gate never collapses two skeleton files.
 */
export const SKELETON: MemoryDocInput[] = [
  {
    path: "core-assets.md",
    type: "Reference",
    title: "Core assets",
    description: "The standing OKF assets the mediator keeps current, and where each kind of knowledge lives.",
    tags: ["okf", "index", "core-assets"],
    body:
      "# Rule\n\n" +
      "Read this map before writing. List every affected standing asset, update each in place, add reciprocal links, and keep latest input as the source of truth — never one concept per task.\n\n" +
      "# Routing map\n\n" +
      "- Architecture change → [Architecture](architecture.md), the affected [design decision](decisions/seed.md), and any standing [risk](risks/seed.md) or convention.\n" +
      "- Decision → [Design decisions](decisions/seed.md) plus every architecture, roadmap, risk, or convention concept it changes.\n" +
      "- Convention → [Test command](conventions/test-command.md) or [Dependency policy](conventions/dependency-policy.md), plus the architecture or roadmap concept affected by the rule.\n" +
      "- Risk → [Open risks](risks/seed.md) plus the decision, architecture, or roadmap concept that owns its mitigation.\n" +
      "- Answered question → [Open questions ledger](questions/open-questions.md) plus every affected decision, architecture, convention, risk, roadmap, or [Glossary](glossary.md) concept. Resolve the ledger entry in the same pass.\n" +
      "- Priority or product/scope change → [Roadmap](roadmap.md) plus each referenced decision, risk, or architecture concept.\n" +
      "- Dependency or test-command change → the affected convention plus [Architecture](architecture.md) or [Roadmap](roadmap.md) when the project shape or priority changes.\n" +
      "- Recurring learning → the existing affected standing concept; use a Learning only when the evidence itself needs a durable home.\n\n" +
      "# Reconcile\n\n" +
      "When new evidence answers an open question, changes a priority, or decides a previously-open concept, fix those states in this same curation pass.\n\n" +
      "# Tail check\n\n" +
      "After multi-asset writes, render the index and validate the whole bundle. Close reciprocal-link gaps before returning.\n",
  },
  {
    path: "architecture.md",
    type: "Architecture",
    title: "Architecture",
    description: "How the system fits together — the standing overview, kept current as structure changes.",
    tags: ["architecture"],
    body: "# Overview\n\n_Seeded placeholder — replace with the real system overview as it is learned._\n\n# Components\n\n# Data flow\n\n# Citations" + ROOT_BACK,
  },
  {
    path: "conventions/test-command.md",
    type: "Convention",
    title: "Test command",
    description: "How this project runs its checks.",
    tags: ["conventions", "testing"],
    body: "# Rule\n\nRun `pnpm test` (vitest), `pnpm test:browser` for the browser suite, and `pnpm build` (tsc). Never spawn extra vitest processes.\n\n# Rationale\n\nOne runner keeps CI and local runs identical.\n\n# Applies to\n\nEvery change.\n\n# Citations" + NESTED_BACK,
  },
  {
    path: "conventions/dependency-policy.md",
    type: "Convention",
    title: "Dependency policy",
    description: "How dependencies are managed.",
    tags: ["conventions", "dependencies"],
    body: "# Rule\n\nDependencies are managed with pnpm. Add one only with a stated reason.\n\n# Rationale\n\nA small, deliberate dependency set is easier to audit and build.\n\n# Applies to\n\nEvery package.json change.\n\n# Citations" + NESTED_BACK,
  },
  {
    path: "decisions/seed.md",
    type: "Decision",
    title: "Design decisions",
    description: "Where the project's design choices are recorded, each with context, rationale, status, and consequences.",
    tags: ["decisions"],
    body: "# Context\n\n_Seeded anchor. File real design choices under decisions/ using this section skeleton, and edit them in place._\n\n# Rationale\n\n# Status\n\n# Consequences\n\n# Citations" + NESTED_BACK,
  },
  {
    path: "risks/seed.md",
    type: "Risk",
    title: "Open risks",
    description: "Standing hazards and their mitigations, kept current as they are found and closed.",
    tags: ["risks"],
    body: "# Risk\n\n_Seeded anchor. Track real hazards under risks/ and keep each one's status current._\n\n# Impact\n\n# Mitigation\n\n# Status\n\n# Citations" + NESTED_BACK,
  },
  {
    path: "glossary.md",
    type: "Reference",
    title: "Glossary",
    description: "Terms of art used across this project, defined once.",
    tags: ["glossary"],
    body: "# Terms\n\n_Seeded placeholder. Define a term the first time it needs pinning down._\n\n# Citations" + ROOT_BACK,
  },
  {
    path: "roadmap.md",
    type: "Reference",
    title: "Roadmap",
    description: "Current direction and priorities, kept current as they shift.",
    tags: ["roadmap"],
    body: "# Direction\n\n_Seeded placeholder. Record the current direction and priorities here._\n\n# Citations" + ROOT_BACK,
  },
];

/**
 * Seed the default core-asset skeleton for a project. Idempotent-ish: an upsert
 * overwrites a same-path asset, so re-seeding restores the scaffold without
 * duplicating. Returns the paths seeded.
 */
export async function seedSkeleton(db: Db, projectId: string): Promise<string[]> {
  const memory = new MemoryStore(db);
  for (const doc of SKELETON) await memory.upsert(projectId, doc);
  return SKELETON.map((d) => d.path);
}
